  (o.events || []).forEach(e => {
    const p = pts[e.i];
    s += `<line x1="${p[0]}" x2="${p[0]}" y1="${p[1] - 9}" y2="${P.t - 8}" stroke="${o.annLine || o.stroke}" stroke-width="1" opacity=".55"/><text x="${p[0]}" y="${P.t - 14}" text-anchor="middle" class="k-ann">${e.text}</text>`;
  });
