  [0, 50, 100].forEach(v => {
    s += `<line x1="${P.l}" x2="${W - P.r}" y1="${y(v)}" y2="${y(v)}" stroke="${o.grid}"/><text x="${P.l - 8}" y="${y(v)}" dy=".34em" text-anchor="end" class="k-ax">${v}</text>`;
  });
