  s += `<path d="${arc(a0, a1, r - 26)}" fill="none" stroke="${o.track}" stroke-width="3" stroke-linecap="round"/><path d="${arc(a0, a0 + (a1 - a0) * p.confidence / 100, r - 26)}" fill="none" stroke="${o.conf}" stroke-width="3" stroke-linecap="round"/>`;
